import numpy as np


class RosenEliteLogJDE:
    """
    Feasibility-first jDE with an evaluation cache and elite archive. Infeasible points are
    ranked by log-violation, so the search follows constraint progress across scales.
    A Rosenbrock-style pattern search with rotating directions refines the best point on
    stall. Learned directions persist across restarts, and restarts reseed around the elite.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        dim = self.dim
        budget = self.budget

        lb = np.asarray(func.bounds.lb, dtype=float).copy()
        ub = np.asarray(func.bounds.ub, dtype=float).copy()
        vtypes = [str(v) for v in func.variable_types]

        is_disc = np.array([v != "continuous" for v in vtypes])
        is_cont = ~is_disc
        is_ord = np.array([v == "ordinal" for v in vtypes])
        is_cat = np.array([v in ("categorical", "binary") for v in vtypes])
        cont_idx = np.where(is_cont)[0]
        disc_idx = np.where(is_disc)[0]
        nc = len(cont_idx)

        width = ub - lb
        nvals = np.ones(dim, dtype=int)
        nvals[is_disc] = np.maximum(np.rint(width[is_disc]).astype(int), 1)

        state = {"evals": 0, "least_v": np.inf, "least_x": None}
        cache = {}
        elite = []
        ELITE_K = 8

        def repair(x):
            x = np.clip(x, lb, ub)
            if np.any(is_disc):
                x[is_disc] = np.clip(np.rint(x[is_disc]), 0, nvals[is_disc] - 1)
            return x

        def can_eval():
            return state["evals"] < budget

        def add_elite(f, x):
            for ef, ex in elite:
                if ef == f and np.array_equal(ex, x):
                    return
            elite.append((f, x.copy()))
            elite.sort(key=lambda t: t[0])
            del elite[ELITE_K:]

        def evaluate(x, F=0.5, CR=0.9, op="I"):
            x = repair(np.asarray(x, dtype=float))
            k = x.tobytes()
            if k in cache:
                f, V = cache[k]
            else:
                f, g = func(x)
                state["evals"] += 1
                f = float(f)
                g = np.asarray(g, dtype=float).ravel()
                g = np.nan_to_num(g, nan=1e9, posinf=1e9, neginf=0.0)
                V = float(np.sum(np.maximum(g, 0.0)))
                if not np.isfinite(f):
                    f = np.inf
                    V = max(V, 1e9)
                cache[k] = (f, V)
                if V == 0.0 and np.isfinite(f):
                    add_elite(f, x)
                if V < state["least_v"]:
                    state["least_v"] = V
                    state["least_x"] = x.copy()
            return {"V": V, "f": f, "x": x, "F": F, "CR": CR, "op": op}

        def key(ind):
            # feasible: ranked by objective; infeasible: ranked by log-violation
            if ind["V"] == 0.0 and np.isfinite(ind["f"]):
                return (0, ind["f"])
            return (1, float(np.log10(ind["V"] + 1e-12)))

        def stratified(n):
            U = np.empty((n, dim))
            for j in range(dim):
                perm = np.random.permutation(n)
                U[:, j] = (perm + np.random.rand(n)) / n
            return lb + U * width

        def discrete_move(x, mask):
            child = x.copy()
            for i in np.where(mask & is_ord)[0]:
                if np.random.rand() < 0.85:
                    child[i] += np.random.choice([-1.0, 1.0])
                else:
                    child[i] = np.random.randint(nvals[i])
            for i in np.where(mask & is_cat)[0]:
                n = nvals[i]
                if n > 1:
                    cur = int(np.rint(child[i]))
                    child[i] = (cur + np.random.randint(1, n)) % n
            return child

        direction = {"d": None}

        def local_move(center, sigma, heavy):
            child = center.copy()
            if direction["d"] is not None and np.random.rand() < 0.3:
                child[is_cont] += np.random.uniform(0.5, 2.0) * direction["d"][is_cont]
                child = repair(child)
                if np.random.rand() < 0.5:
                    return child
            mask = np.random.rand(dim) < max(1.0 / dim, min(1.0, 2.0 / dim))
            if not np.any(mask):
                mask[np.random.randint(dim)] = True
            m = mask & is_cont
            if np.any(m):
                if heavy:
                    step = np.clip(np.random.standard_cauchy(np.count_nonzero(m)), -5, 5)
                else:
                    step = np.random.randn(np.count_nonzero(m))
                child[m] += sigma * width[m] * step
            child = discrete_move(child, mask)
            return repair(child)

        def gram(vectors, limit):
            B = []
            for v in vectors:
                w = v.copy()
                for b in B:
                    w -= np.dot(w, b) * b
                for b in B:
                    w -= np.dot(w, b) * b
                n = np.linalg.norm(w)
                if n > 1e-10:
                    B.append(w / n)
                if len(B) >= limit:
                    break
            return B

        def rosen_search(anchor, steps, Q):
            best = anchor
            if nc > 0:
                disp = np.zeros((nc, dim))
                succ = np.zeros(nc, dtype=int)
                for j in np.random.permutation(nc):
                    if not can_eval():
                        break
                    d = Q[j]
                    improved = False
                    tot = np.zeros(dim)
                    for sgn in (1.0, -1.0):
                        moved = True
                        while moved and can_eval():
                            x = best["x"].copy()
                            x[cont_idx] += sgn * steps[j] * d[cont_idx] * width[cont_idx]
                            cand = evaluate(x, op="C")
                            moved = False
                            if key(cand) < key(best):
                                zd = np.zeros(dim)
                                zd[cont_idx] = (cand["x"][cont_idx] - best["x"][cont_idx]) / width[cont_idx]
                                tot += zd
                                best = cand
                                improved = True
                                steps[j] = min(1.0, steps[j] * 2.0)
                                moved = True
                        if improved:
                            break
                    if improved:
                        succ[j] += 1
                        disp[j] = tot
                    else:
                        steps[j] = max(1e-6, steps[j] * 0.5)

                # Rosenbrock rotation towards successful displacements
                if np.any(succ > 0):
                    order = [j for j in np.argsort(-succ) if succ[j] > 0]
                    vecs = [disp[j] for j in order] + [Q[j] for j in range(nc)]
                    B = gram(vecs, nc)
                    if len(B) < nc:
                        units = []
                        for i in cont_idx:
                            e = np.zeros(dim)
                            e[i] = 1.0
                            units.append(e)
                        B = gram(B + units, nc)
                    if len(B) == nc:
                        Q = np.array(B)
                        steps = np.maximum(steps, 1e-4)

            # Discrete coordinate probes
            if can_eval() and len(disc_idx) > 0:
                nprobe = min(2, len(disc_idx))
                for i in np.random.choice(disc_idx, nprobe, replace=False):
                    if not can_eval():
                        break
                    x = best["x"].copy()
                    if is_ord[i]:
                        x[i] += np.random.choice([-1.0, 1.0])
                    elif is_cat[i] and nvals[i] > 1:
                        x[i] = (int(np.rint(x[i])) + np.random.randint(1, nvals[i])) % nvals[i]
                    cand = evaluate(x, op="C")
                    if key(cand) < key(best):
                        best = cand
            return best, steps, Q

        # ---- Parameters ----
        n0 = int(max(4, min(5 * dim + 10, budget // 5)))
        mu = int(max(6, min(30, 4 * dim, n0 // 2)))
        lam = 2 * mu
        patience = 4
        sigma = 0.1
        sigma_min, sigma_max = 1e-4, 0.5
        p_local = 0.35
        loc_succ, loc_tot = 0, 0
        steps = np.full(max(nc, 1), 0.05)
        Q = np.zeros((nc, dim))
        if nc > 0:
            Q[np.arange(nc), cont_idx] = 1.0
        guard = 0
        max_guard = 50 * budget + 1000

        # ---- Initial design ----
        pop = []
        for x in stratified(n0):
            if not can_eval():
                break
            pop.append(evaluate(x))
        if not pop:
            return float("inf"), None
        pop.sort(key=key)
        pop = pop[:mu]

        best_key = key(pop[0])
        stall = 0

        # ---- Main loop ----
        while can_eval() and guard < max_guard:
            guard += 1
            children = []
            incumbent = pop[0]
            n_top = max(2, len(pop) // 4)
            for i in range(lam):
                if not can_eval():
                    break
                target = pop[i % len(pop)]
                F = target["F"]
                CR = target["CR"]
                if np.random.rand() < 0.1:
                    F = 0.1 + 0.9 * np.random.rand()
                if np.random.rand() < 0.1:
                    CR = np.random.rand()

                if np.random.rand() < p_local:
                    if elite and np.random.rand() < 0.7:
                        if np.random.rand() < 0.6:
                            anchor = elite[0][1]
                        else:
                            anchor = elite[np.random.randint(len(elite))][1]
                    else:
                        anchor = incumbent["x"]
                    heavy = np.random.rand() < 0.25
                    cx = local_move(anchor, sigma, heavy)
                    ch = evaluate(cx, F, CR, op="L")
                    ch["anchor_key"] = key(incumbent)
                    ch["anchor_x"] = anchor
                    children.append(ch)
                else:
                    if len(pop) >= 3:
                        r1, r2 = np.random.choice(len(pop), 2, replace=False)
                    else:
                        r1, r2 = np.random.randint(len(pop)), np.random.randint(len(pop))
                    xr1, xr2 = pop[r1]["x"], pop[r2]["x"]
                    xt = target["x"]
                    xb = pop[np.random.randint(n_top)]["x"]
                    mutant = xt + F * (xb - xt) + F * (xr1 - xr2)
                    jrand = np.random.randint(dim)
                    cr_mask = np.random.rand(dim) < CR
                    cr_mask[jrand] = True
                    trial = np.where(cr_mask, mutant, xt)
                    dmask = (np.random.rand(dim) < 1.0 / dim) & is_disc
                    trial = discrete_move(trial, dmask)
                    cmask = (np.random.rand(dim) < 1.0 / dim) & is_cont
                    if np.any(cmask):
                        trial[cmask] += 0.01 * width[cmask] * np.random.randn(np.count_nonzero(cmask))
                    children.append(evaluate(repair(trial), F, CR, op="D"))

            if not children:
                break

            # 1/5-rule adaptation and direction learning
            for c in children:
                if c["op"] == "L":
                    loc_tot += 1
                    if key(c) < c["anchor_key"]:
                        loc_succ += 1
                        d = np.zeros(dim)
                        d[is_cont] = (c["x"] - c["anchor_x"])[is_cont]
                        direction["d"] = d
                    if loc_tot >= 10:
                        rate = loc_succ / loc_tot
                        if rate > 0.2:
                            sigma = min(sigma_max, sigma * 1.5)
                            p_local = min(0.6, p_local + 0.03)
                        else:
                            sigma = max(sigma_min, sigma * 0.82)
                            p_local = max(0.1, p_local - 0.03)
                        loc_succ, loc_tot = 0, 0

            pop = sorted(pop + children, key=key)[:mu]

            cur_key = key(pop[0])
            if cur_key < best_key:
                best_key = cur_key
                stall = 0
            else:
                stall += 1

            # Rosenbrock pattern search on the best point when stalling
            if stall >= 2 and can_eval():
                if elite:
                    anchor = evaluate(elite[0][1], op="I")
                else:
                    anchor = pop[0]
                best_c, steps, Q = rosen_search(anchor, steps, Q)
                if key(best_c) < key(pop[0]):
                    pop = sorted([best_c] + pop, key=key)[:mu]
                    best_key = key(pop[0])
                    stall = 0

            # Stagnation restart seeded from the elite archive
            if stall >= patience and can_eval():
                new_pop = []
                if elite:
                    new_pop.append(evaluate(elite[0][1], 0.5, 0.9, op="I"))
                n_fresh = max(2, mu // 3)
                for x in stratified(n_fresh):
                    if len(new_pop) >= mu or not can_eval():
                        break
                    new_pop.append(evaluate(x, 0.5, 0.9))
                scales = [max(1e-4, sigma * 0.2), max(1e-3, sigma), 0.3]
                tries = 0
                while len(new_pop) < mu and can_eval() and tries < 20 * mu:
                    tries += 1
                    if elite:
                        base = elite[np.random.randint(len(elite))][1]
                    else:
                        base = pop[0]["x"]
                    s_r = scales[np.random.randint(len(scales))]
                    new_pop.append(evaluate(local_move(base, s_r, False), 0.5, 0.9, op="I"))
                if new_pop:
                    pop = sorted(new_pop, key=key)[:mu]
                    best_key = key(pop[0])
                stall = 0
                sigma = 0.05
                # keep learned directions, only reset step lengths to a moderate scale
                steps = np.maximum(steps * 0.5, 0.02) if nc > 0 else steps
                direction["d"] = None

        if elite:
            return float(elite[0][0]), elite[0][1]
        return float("inf"), state["least_x"]
